akJ(a,b,c,d){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 "+a+" \u0639\u062f\u062f\u064b\u0627 \u0635\u062d\u064a\u062d\u064b\u0627 \u0628\u064a\u0646 "+b+" \u0648"+c+"\u060c \u0645\u0646 \u0645\u0636\u0627\u0639\u0641\u0627\u062a "+d},
ganc(){return"\u0645\u062f\u0629 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629. \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0645\u062f\u0629 \u0627\u0644\u0643\u0634\u0651\u0627\u0641 15 \u0623\u0648 30 \u0623\u0648 60 \u064a\u0648\u0645\u064b\u0627."},
gam4(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0643\u0634\u0651\u0627\u0641 \u0645\u062a\u0641\u0631\u063a. \u0648\u0638\u0651\u0641 \u0643\u0634\u0651\u0627\u0641\u064b\u0627 \u0645\u0646 \u0645\u0643\u062a\u0628 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0623\u0648 \u0627\u0646\u062a\u0638\u0631 \u0627\u0646\u062a\u0647\u0627\u0621 \u0625\u062d\u062f\u0649 \u0627\u0644\u0645\u0647\u0627\u0645."},
