gagH(){return"\u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0627\u0644\u0631\u0648\u0627\u062a\u0628 \u0643\u0644\u0647\u0627 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0627\u0644\u0639\u0642\u0648\u062f: \u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u062d\u0648\u064a\u0644 \u0645\u0627 \u0627\u0644\u062a\u064f\u0632\u0645 \u0628\u0647. \u0627\u062e\u062a\u0631 \u062e\u0632\u064a\u0646\u0629 \u0623\u062e\u0631\u0649."},
gagC(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062e\u0632\u064a\u0646\u0629 \u0645\u0633\u0627\u062d\u0629 \u0641\u0627\u0631\u063a\u0629 \u0628\u0647\u0630\u0627 \u0627\u0644\u0642\u062f\u0631\u061b \u0642\u0644\u0651\u0644 \u0627\u0644\u0645\u0628\u0644\u063a \u0623\u0648 \u0627\u062e\u062a\u0631 \u062e\u0632\u064a\u0646\u0629 \u0623\u062e\u0631\u0649."},
